package io.forgeloop.control.api;
import io.forgeloop.control.application.LeaseGrant; import io.forgeloop.control.application.RunnerService; import io.forgeloop.control.application.TaskLeaseService; import io.forgeloop.control.domain.TaskLease; import org.springframework.graphql.data.method.annotation.*; import org.springframework.stereotype.Controller;
/** Runner-facing mutations are deliberately separated from operator control-plane mutations. */
@Controller public class RunnerExecutionController { private final TaskLeaseService leases; private final RunnerService runners; public RunnerExecutionController(TaskLeaseService leases,RunnerService runners){this.leases=leases;this.runners=runners;} @MutationMapping public LeaseGrant claimTaskLease(@Argument String taskId,@Argument String runnerId,@Argument String credential){runners.authenticated(runnerId,credential);return leases.claim(taskId,runnerId);}@MutationMapping public TaskLease acknowledgeTaskLease(@Argument String leaseId,@Argument String runnerId,@Argument String nonce,@Argument String credential){runners.authenticated(runnerId,credential);return leases.acknowledge(leaseId,runnerId,nonce);}@MutationMapping public TaskLease completeTaskLease(@Argument String leaseId,@Argument String runnerId,@Argument String nonce,@Argument String credential,@Argument boolean passed){runners.authenticated(runnerId,credential);return leases.complete(leaseId,runnerId,nonce,passed);} }
